head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF90701";
scwin.id_equalChrg = null;
scwin.reg_button = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — comAttrTpCdList, transstkAgntCdList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.id_equalChrg = $c.util.getComponent('id_equalChrg');
        scwin.reg_button = $c.util.getComponent('reg_button');
        scwin.init_fillGen();
        scwin.init_conds();
        scwin.init_datefmt_cal_foundDd();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf90701.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "slc_acntclsMm1", fn: function(){ return ((dma_map.get("acntclsMmdd1") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd1"); })()) !== ''); } }, { id: "slc_acntclsMm2", fn: function(){ return ((dma_map.get("acntclsMmdd2") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd2"); })()) !== ''); } }, { id: "slc_acntclsMm3", fn: function(){ return ((dma_map.get("acntclsMmdd3") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd3"); })()) !== ''); } }, { id: "slc_acntclsMm4", fn: function(){ return ((dma_map.get("acntclsMmdd4") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd4"); })()) !== ''); } }, { id: "slc_acntclsMm5", fn: function(){ return ((dma_map.get("acntclsMmdd5") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd5"); })()) !== ''); } }, { id: "slc_acntclsMm6", fn: function(){ return ((dma_map.get("acntclsMmdd6") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd6"); })()) !== ''); } }, { id: "slc_acntclsMm7", fn: function(){ return ((dma_map.get("acntclsMmdd7") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd7"); })()) !== ''); } }, { id: "slc_acntclsMm8", fn: function(){ return ((dma_map.get("acntclsMmdd8") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd8"); })()) !== ''); } }, { id: "slc_acntclsMm9", fn: function(){ return ((dma_map.get("acntclsMmdd9") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd9"); })()) !== ''); } }, { id: "slc_acntclsMm10", fn: function(){ return ((dma_map.get("acntclsMmdd10") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd10"); })()) !== ''); } }, { id: "slc_acntclsMm11", fn: function(){ return ((dma_map.get("acntclsMmdd11") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd11"); })()) !== ''); } }, { id: "slc_acntclsMm12", fn: function(){ return ((dma_map.get("acntclsMmdd12") ?? (() => { throw new Error("unresolved:" + "map.acntclsMmdd12"); })()) !== ''); } }, { id: "if_cdVal", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cdVal"); })() === '1'); } }, { id: "if_cdVal_2", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cdVal"); })() === '2'); } }, { id: "if_cdVal_3", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "row.cdVal"); })() !== '1' && (() => { throw new Error("unresolved:data:" + "row.cdVal"); })() !== '2'); } }, { id: "c_when_354", fn: function(){ return (!(String(((dma_pageContext.get("comAttrTpCdList") ?? "")) == null ? '' : ((dma_pageContext.get("comAttrTpCdList") ?? ""))).length === 0)); } }, { id: "rd_transstkAgntCd", fn: function(){ return (!(String(((dma_pageContext.get("transstkAgntCdList") ?? "")) == null ? '' : ((dma_pageContext.get("transstkAgntCdList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_355", entity: "dlt_comAttrTpCdList", countIds: [], cells: [{ childId: "option_357", fn: function (v, i) { return String(v("cdVal")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("cdVal")) + " 주식회사"; } }, { childId: "option_359", fn: function (v, i) { return String(v("cdVal")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("cdVal")) + " 증권투자회사"; } }, { childId: "option_361", fn: function (v, i) { return String(v("cdVal")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("cdVal")) + " " + String(v("cdValNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_datefmt_cal_foundDd
 * @description 초기화 — datefmt cal found Dd
 * @returns {void}
