 */
scwin.init_datefmt_cal_foundDd = function () { $c.date.checkCalendarFormat("cal_foundDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.setRegNoData();
        scwin.setChrgData();
        scwin.setInitDisplay();
        const com_attr_tp_cd = $c.util.getComponent('slc_comAttrTpCd').getValue();
        if (com_attr_tp_cd === '5' || com_attr_tp_cd === '7') {
            (($c.util.getComponent('ipt_regNot')) && ($c.util.getComponent('ipt_regNot')).setValue ? ($c.util.getComponent('ipt_regNot')).setValue((false) === 'disabled' || (false) === 'readonly' || (false) === 'checked' ? true : (false)) : void 0);
            $c.util.getComponent('ipt_notiSchdlDd').setValue("");
            $c.util.getComponent('ipt_nregRsn').setValue("");
            (($c.util.getComponent('ipt_regNot')) && ($c.util.getComponent('ipt_regNot')).setDisabled ? ($c.util.getComponent('ipt_regNot')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
        }
        scwin.setAcntcls_mm();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90701.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

