/**
 * @method
 * @name setRegNoData
 * @description set Reg No Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setRegNoData = function () {
    let corpRegNo = $c.util.getComponent('ipt_corpRegNoP').getValue(); if (corpRegNo == null) { corpRegNo = ''; }
    if (corpRegNo !== '') {
        const corpRegNos = corpRegNo.split("-");
        if (corpRegNos.length > 0) {
            $c.util.getComponent('ipt_corpRegNo1').setValue(corpRegNos[0]);
        }
        if (corpRegNos.length > 1) {
            $c.util.getComponent('ipt_corpRegNo2').setValue(corpRegNos[1]);
        }
        $c.util.getComponent('ipt_corpRegNoE').setValue(corpRegNo);
    }
    let bzRegNo = $c.util.getComponent('ipt_bzRegNoP').getValue(); if (bzRegNo == null) { bzRegNo = ''; }
    if (bzRegNo !== '') {
        const bzRegNos = bzRegNo.split("-");
        if (bzRegNos.length > 0) {
            $c.util.getComponent('ipt_bzRegNo1').setValue(bzRegNos[0]);
        }
        if (bzRegNos.length > 1) {
            $c.util.getComponent('ipt_bzRegNo2').setValue(bzRegNos[1]);
        }
        if (bzRegNos.length > 2) {
            $c.util.getComponent('ipt_bzRegNo3').setValue(bzRegNos[2]);
        }
        $c.util.getComponent('ipt_bzRegNoE').setValue(corpRegNo);
    }
};

/**
 * @method
 * @name setChrgData
 * @description set Chrg Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.setChrgData = function () {
    $c.util.getComponent('ipt_chrgNm1').setValue('' + dma_map.get("chrgNmCvt") + '');
    const cntr_cd = $c.util.getComponent('ipt_cntrCd').getValue();
    const tel = '' + dma_map.get("chrgTelNoCvt") + '';
    if (tel !== '') {
        if (cntr_cd === "410") {
            const tels = tel.split("-");
            if (tels.length > 0) {
                $c.util.getComponent('ipt_chrgTelNo1').setValue(tels[0]);
            }
            if (tels.length > 1 && tels[1].length < 5) {
                $c.util.getComponent('ipt_chrgTelNo2').setValue(tels[1]);
            } else {
                if (tels[1].length > 4) {
                    $c.util.getComponent('ipt_chrgTelNo2').setValue(tels[1].substring(0, 4));
                    $c.util.getComponent('ipt_chrgTelNo3').setValue(tels[1].substring(4, 8));
                }
            }
            if (tels.length > 2) {
                $c.util.getComponent('ipt_chrgTelNo3').setValue(tels[2]);
            }
            $c.util.getComponent('ipt_chrgInnrNo1').setValue($c.util.getComponent('ipt_chrgInnrNo').getValue());
        } else {
            $c.util.getComponent('ipt_chrgTelNoFor').setValue(tel);
            $c.util.getComponent('ipt_chrgInnrNoFor').setValue($c.util.getComponent('ipt_chrgInnrNo').getValue());
        }
    }
    $c.util.getComponent('ipt_chrgInnrNo').setValue($c.util.getComponent('ipt_chrgInnrNo').getValue());
    $c.util.getComponent('ipt_chrgTelNo').setValue('' + dma_map.get("chrgTelNoCvt") + '');
    const fax = '' + dma_map.get("chrgFaxNoCvt") + '';
    if (fax !== '') {
        if (cntr_cd === "410") {
            const faxs = fax.split("-");
            if (faxs.length > 0) {
                $c.util.getComponent('ipt_chrgFaxNo1').setValue(faxs[0]);
            }
            if (faxs.length > 1 && faxs[1].length < 5) {
                $c.util.getComponent('ipt_chrgFaxNo2').setValue(faxs[1]);
            } else {
                if (faxs[1].length > 4) {
                    $c.util.getComponent('ipt_chrgFaxNo2').setValue(faxs[1].substring(0, 4));
                    $c.util.getComponent('ipt_chrgFaxNo3').setValue(faxs[1].substring(4, 8));
                }
            }
            if (faxs.length > 2) {
